<?php defined('ABSPATH')||exit; $term=$args['term']??null; $number=$args['number']??'01'; if(!$term||is_wp_error($term))return; $url=get_term_link($term); if(is_wp_error($url))return; $image_id=(int)get_term_meta($term->term_id,'thumbnail_id',true); $image_alt=$image_id?(get_post_meta($image_id,'_wp_attachment_image_alt',true)?:$term->name):$term->name; ?> <a class="bp-category-card" href="<?php echo esc_url($url); ?>"> <span class="bp-category-card__number" aria-hidden="true"><?php echo esc_html($number); ?></span> <figure class="bp-category-card__media"> <?php if($image_id): ?> <?php echo wp_get_attachment_image($image_id,'medium_large',false,['class'=>'bp-category-card__image','alt'=>$image_alt,'loading'=>'lazy','decoding'=>'async']); ?> <?php else: ?> <span class="bp-category-card__placeholder" aria-hidden="true"></span> <?php endif; ?> </figure> <div class="bp-category-card__footer"> <div class="bp-category-card__title-wrap"> <h3 class="bp-category-card__title"><?php echo esc_html($term->name); ?></h3> <svg class="bp-category-card__arrow" viewBox="0 0 24 24" width="18" height="18" fill="none" aria-hidden="true"> <path d="M19 12H5m0 0 7-7m-7 7 7 7" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/> </svg> </div> <span class="bp-category-card__count"><?php echo number_format_i18n((int)$term->count); ?> محصول</span> </div> </a>